const fs = require('fs');
const { chapter, ROOT } = require('./lib.js');
const L = chapter(4, 'CHAPTER 4: RESULTS AND DISCUSSION', 'CHAPTER 4 thesis.docx');
const J = JSON.parse(fs.readFileSync(`${ROOT}/results/thesis/ch5_data.json`, 'utf8')); const A = J.F, T = J.T;
const { add, H1, H2, H3, table, caption, figure, afterTable, n } = L;
const P = (s) => L.P(s); const ref = (l) => L.ref(l); const cit = (...k) => L.cit(...k);
const f = (x, d = 3) => Number(x).toFixed(d);
const sg = (x, d = 3) => (x >= 0 ? '+' : '−') + Math.abs(x).toFixed(d);
const I = (k, s, r, m = 'mcc', d = 3) => f(A.ind[k][s][r][m], d);
const G = (k) => A.gaps[k];
const ci = (o, d = 3) => `${sg(o.dmcc, d)} [${sg(o.lo, d)}, ${sg(o.hi, d)}]`;
const RF = 'AAC_RF', M650 = 'esm2_t33_650M_lam0_tau0.07', M8 = 'esm2_t6_8M_lam0_tau0.07', FT = 'esm2_t6_8M_finetune', FZ = 'esm2_t6_8M_frozen';
const shade = (k) => ({ shadeRows: T[k + '_shade'] || T.cv_shade, size: 17 });
const H = A.h1, FM = A.fam, ND = A.nested, MD = A.mde;
const rep = A.rep;
const rp = (k, s) => rep[`${k}|${s}`];
const readCsv = (p) => { const L_ = fs.readFileSync(p, 'utf8').trim().split('\n'); const row = (l) => { const o = []; let cur = '', q = false; for (const ch of l) { if (ch === '"') q = !q; else if (ch === ',' && !q) { o.push(cur); cur = ''; } else cur += ch; } o.push(cur); return o; }; const H_ = row(L_[0]); return L_.slice(1).map((l) => Object.fromEntries(row(l).map((v, k) => [H_[k], v]))); };
const GAPC = readCsv(`${ROOT}/results/tables/T5.12b_leakage_gap_family_contrasts.csv`);
const gc = (name, scope, fld) => Number(GAPC.find((r) => r.contrast === name && r.scope === scope)[fld]);
const RT = (name, set) => T.rep_tests.find((r) => r[0] === name && r[1] === set);

// ---------------------------------------------------------------- intro
add(H1('CHAPTER 4: RESULTS AND DISCUSSION'));
add(P(`This chapter reports the results in the order of the questions of Chapter 1. Section 4.1 gives the cross-validated performance of all models, Sections 4.2 and 4.3 the performance on the two independent sets under the three evaluation regimes of Chapter 3, and Section 4.4 the effect of the overlap between the training collection and the independent sets, which is the principal finding of the thesis. Section 4.5 tests whether the supervised contrastive objective (SupCon) improves prediction, in the pre-registered hypotheses and in the wider set of comparisons, Section 4.6 examines how the frozen representation compares with composition features and with a fine-tuned model, Section 4.7 relates the results to published predictors, and Section 4.8 states what the test sets were able to detect. Sections 4.9 and 4.10 discuss the results and their limitations.`));
add(P(`<b>Reading the tables.</b> Three kinds of numbers are reported, and they should not be mixed. (i) Cross-validation scores (Table ${ref('tab:cv')}) are the mean ± standard deviation over the 25 runs (five repetitions of five folds) of one configuration; the runs share training data, so the standard deviation describes the spread between runs and is not a confidence interval. (ii) Scores on the independent sets (Tables ${ref('tab:ind425')} and ${ref('tab:ind1049')} of Appendix A) are the mean over the five final models of one configuration, each trained on all of Benchmark_clean with a different seed. (iii) The paired differences and p-values of the statistical tests (Sections 4.4 to 4.8) use the ensemble of the five final models (the average of their predicted probabilities) and a threshold of 0.5, so that they can differ from (ii) for the neural models. Unless stated otherwise, ΔMCC is the difference between the MCC of the model with λ > 0 and the model with λ = 0, or between the first and the second model named in a comparison, with a 95% confidence interval from 2,000 paired stratified bootstrap resamples; the p-value reported next to it is the DeLong p-value for the difference in AUROC, as pre-registered (Section 3.14). The adjusted p-values use the Benjamini–Hochberg procedure ${cit('benjamini1995')} within the family named in the table, and ${A.n_tests} comparisons were corrected globally. The tier of an analysis (primary, secondary, exploratory) is stated where it matters.`));

// ---------------------------------------------------------------- 5.1
add(H2('4.1 Cross-Validated Performance of All Models'));
add(P(`Table ${ref('tab:cv')} lists the 5 × 5 cross-validated performance of every model on Benchmark_clean (3,716 sequences). The best of all models is the random forest on amino acid composition (AAC + RF), with MCC ${f(A.cv_mean.AAC_RF.mcc)} and AUROC ${f(A.cv_mean.AAC_RF.auroc)}. It is followed by the random forest on the hand-crafted features (composition, dipeptide composition and the CTD descriptors, MCC ${f(A.fus_cv['hand|rf'].mcc)}), LightGBM on the same features (${f(A.cv_mean.AAC_DPC_CTD_LGBM.mcc)}), and the random forest on the 8M embedding concatenated with the hand-crafted features (${f(A.fus_cv['esm8_fusion|rf'].mcc)}). The fine-tuned 8M model reaches MCC ${f(A.ft_cv.esm2_t6_8M_finetune.mcc)} (AUROC ${f(A.ft_cv.esm2_t6_8M_finetune.auroc)}; 15 runs), which places it in this group.`));
add(P(`Every model that uses a frozen ESM-2 embedding on its own is clearly lower: logistic regression on the 8M, 35M and 150M embeddings gives MCC ${f(A.cv_mean.esm2_t6_8M_LR.mcc)}, ${f(A.cv_mean.esm2_t12_35M_LR.mcc)} and ${f(A.cv_mean.esm2_t30_150M_LR.mcc)}, and the multilayer perceptron with λ = 0 gives ${f(A.cv_mean[M8].mcc)} (8M), ${f(A.cv_mean['esm2_t12_35M_lam0_tau0.07'].mcc)} (35M), ${f(A.cv_mean['esm2_t30_150M_lam0_tau0.07'].mcc)} (150M) and ${f(A.cv_mean[M650].mcc)} (650M). Within this family the larger checkpoints are better, but the difference between the 150M and 650M models is negligible, and none comes within ${f(A.cv_mean.AAC_RF.mcc - A.cv_mean['esm2_t30_150M_lam2_tau0.07'].mcc, 2)} MCC of AAC + RF. Among the residue-level architectures on the frozen 8M embedding, the Transformer (B5) is the clear best (MCC ${f(A.ft_cv.B5_transformer_lam0.mcc)} at λ = 0), and the others lie between ${f(A.cv_mean.B4_cnn_bilstm_lam0.mcc)} (B4) and ${f(A.cv_mean.B2_cnn_lam0.mcc)} (B2), in the range of the multilayer perceptron. The contrastive models (rows with SupCon or λ = 2) differ from their λ = 0 counterparts by 0.001 to 0.014 MCC, which is within the spread between runs; they are analysed in Section 4.5.`));
add(caption('tab:cv', 'Five-fold cross-validated performance on Benchmark_clean (mean ± standard deviation over 25 runs; 15 runs for the fine-tuning experiment). Shaded rows name the group of models below them. Rows with λ > 0 use the CV-selected λ and τ. Source: results/thesis/ch5_data.json, built from the cross-validation result files.'));
add(table(T.cv, [3400, 560, 1080, 1080, 1080, 1080, 1060], shade('cv')), afterTable());
add(P(`One caution applies to the whole table: all models were evaluated on the same folds of the same collection, which, as Section 4.4 shows, contains clusters of related sequences. The cross-validated scores therefore estimate performance on peptides resembling the training peptides and are a ranking of the models on this collection, not a forecast for new peptides.`));

// ---------------------------------------------------------------- 5.2
add(H2('4.2 Performance on the Independent Sets as Distributed (Regime A)'));
add(P(`Tables ${ref('tab:ind425')} and ${ref('tab:ind1049')} of Appendix A give the MCC and AUROC of every model on the two independent sets in the three regimes; the comparisons that carry the argument are drawn out below and in Section 4.4. Regime A is the evaluation as the sets were distributed. In this regime the models reach considerably higher scores than in cross-validation: AAC + RF has MCC ${I(RF, 'ind_425', 'A')} and AUROC ${I(RF, 'ind_425', 'A', 'auroc')} on Ind_425 and MCC ${I(RF, 'ind_1049', 'A')} and AUROC ${I(RF, 'ind_1049', 'A', 'auroc')} on Ind_1049, against ${f(A.cv_mean.AAC_RF.mcc)} and ${f(A.cv_mean.AAC_RF.auroc)} in cross-validation. The frozen 650M model with λ = 0 has ${I(M650, 'ind_425', 'A')} and ${I(M650, 'ind_1049', 'A')}, the fine-tuned 8M model ${I(FT, 'ind_425', 'A')} and ${I(FT, 'ind_1049', 'A')}.`));
add(P(`Two things should be noticed. First, the independent sets appear easier than the held-out folds of the benchmark, in particular for the composition-based models, which is not what independent data normally does. Second, the top of the ranking in Regime A is the same kind of model as in cross-validation: on Ind_425 the three best models are AAC + RF (${I(RF, 'ind_425', 'A')}) and the random forests on the hand-crafted features and on the fused 8M features, and on Ind_1049 the three best are the random forest on the hand-crafted features (${I('hand|rf', 'ind_1049', 'A')}), the random forest on the fused 8M features (${I('esm8_fusion|rf', 'ind_1049', 'A')}) and AAC + RF (${I(RF, 'ind_1049', 'A')}), so that Regime A does not alter which family of representation is better; it alters the apparent size of the scores, which Section 4.4 explains.`));

// ---------------------------------------------------------------- 5.3
add(H2('4.3 Performance after Removing the Overlap (Regimes B and C)'));
add(P(`Regime B removes from each independent set the sequences that also occur in Benchmark_clean (211 sequences of Ind_425 and 298 of Ind_1049), and Regime C also removes those with a sequence identity of at least 0.9 to any benchmark sequence (Chapter 3). In Regime B, AAC + RF has MCC ${I(RF, 'ind_425', 'B')} (AUROC ${I(RF, 'ind_425', 'B', 'auroc')}) on Ind_425 and ${I(RF, 'ind_1049', 'B')} (${I(RF, 'ind_1049', 'B', 'auroc')}) on Ind_1049; the frozen 650M model has ${I(M650, 'ind_425', 'B')} and ${I(M650, 'ind_1049', 'B')}; the fine-tuned 8M model ${I(FT, 'ind_425', 'B')} and ${I(FT, 'ind_1049', 'B')}; and the Transformer B5 ${I('B5_transformer_lam0', 'ind_425', 'B')} and ${I('B5_transformer_lam0', 'ind_1049', 'B')}. Every one of the 48 configurations evaluated on both sets scores lower in Regime B than in Regime A on both sets, and the Regime B scores of the frozen-embedding models (MCC 0.1 to 0.33) are low in absolute terms, so that, under leakage-free evaluation, none of the models predicts AIPs with high reliability.`));
add(P(`Regime C gives almost the same results as Regime B. For the models in Table ${ref('tab:gaps')}, the drop from Regime A to Regime C differs from the drop to Regime B by at most ${f(Math.max(...Object.values(A.gaps).flatMap((g) => [Math.abs(g.mC425 - g.m425), Math.abs(g.mC1049 - g.m1049)])), 3)} MCC, so that removing near-duplicates (identity of 0.9 or more) beyond the exact matches changes the scores very little. The identity screen removes only 52 further sequences from Ind_425 (214 to 162) and 35 from Ind_1049 (751 to 716). For this reason Regime B is used as the reference evaluation in the following sections; Regime B also leaves more sequences (214 and 751) than Regime C (162 and 716), which matters for statistical power (Section 4.8).`));
add(P(`In Regime B the best model on Ind_425 is AAC + RF (MCC ${I(RF, 'ind_425', 'B')}); on Ind_1049 the highest MCC is reached by the LightGBM model on the 8M embedding fused with the hand-crafted features (${I('esm8_fusion|lgbm', 'ind_1049', 'B')}), with AAC + RF at ${I(RF, 'ind_1049', 'B')}. The intervals of Section 4.8 show that these differences between the top composition-based and fusion models are of the order of the minimum detectable effect, so that no claim of a winner among them is made. What the data do support is a gap between the best composition-based models and the frozen-embedding models of about 0.1 to 0.2 MCC in Regime B, and the fact that fine-tuning narrows it (Section 4.6).`));

// ---------------------------------------------------------------- 5.4
add(H2('4.4 The Impact of Overlap between Training and Test Data'));
add(P(`This section carries the central result of the thesis. The two standard resources for AIP prediction, the AIPpred and AntiInflam datasets, are each free of internal duplicates, and each contains a training and an independent partition without any shared sequence. The benchmark collection used here combines the training sequences of both resources, and the independent sets are the independent partitions of the two. Chapter 3 documented that the sequences shared between the combined collection and the independent sets come from the other resource, so that a model trained on the combined file, or on one resource and tested on the independent set of the other, is partly tested on peptides it has seen. This section quantifies what that does to the measured performance.`));
add(H3('4.4.1 How much of each independent set is shared'));
add(P(`Of the 425 sequences of Ind_425, 211 (49.6%) occur in the benchmark, and of the 1,049 sequences of Ind_1049, 298 (28.4%). In 204 of the 211 shared sequences of Ind_425 and in 286 of the 298 of Ind_1049, the label in the independent set agrees with the label in the benchmark; the labels are opposite in only 7 and 12 sequences. A model that memorises its training peptides is therefore rewarded for those test peptides, and almost never penalised, which is what makes the effect an inflation and not a noise term. The overlap is visible in the lineage of the files (Figure ${ref('fig:lineage')}): the independent set of AIPpred is identical to Ind_1049, the validation set of AntiInflam is identical to Ind_425, and the benchmark contains the AIPpred benchmark and 612 AntiInflam training sequences. The two independent sets also have 77 sequences in common with each other.`));
add(H3('4.4.2 The size of the effect'));
add(P(`Table ${ref('tab:gaps')} reports the drop in MCC and in AUROC from Regime A to Regime B for every model for which all three regimes were evaluated. Every model drops in both measures on both sets. The MCC drop (A − B) ranges from ${f(A.gap_range_mcc.min, 3)} to ${f(A.gap_range_mcc.max, 3)} over all ${Object.keys(A.gaps).length} evaluated configurations on the two sets (Table ${ref('tab:gaps')} shows a selection), and the AUROC drop ranges from 0.025 to 0.206. For AAC + RF, the best composition-based model, the MCC falls from ${I(RF, 'ind_425', 'A')} to ${I(RF, 'ind_425', 'B')} on Ind_425 (${f(G(RF).m425)}) and from ${I(RF, 'ind_1049', 'A')} to ${I(RF, 'ind_1049', 'B')} on Ind_1049 (${f(G(RF).m1049)}); the AUROC falls by ${f(G(RF).a425)} and ${f(G(RF).a1049)}. For the support vector machine on composition the MCC falls by ${f(G('AAC_SVM').m425)} and ${f(G('AAC_SVM').m1049)}.`));
add(caption('tab:gaps', 'Drop in performance from Regime A (as distributed) to Regime B (exact matches removed) and to Regime C (identity ≥ 0.9 also removed), for the models evaluated in all regimes. Positive values mean that the score is lower after removal. Source: results/thesis/ch5_data.json.'));
add(table(T.gaps, [3000, 1000, 1000, 1000, 1000, 1180, 1180], { size: 17 }), afterTable());
add(H3('4.4.3 Is the inflation a function of model capacity?'));
add(P(`A natural expectation is that models with higher capacity profit more from the overlap, because they are better able to memorise training peptides. The data support a weaker statement. The drop is smallest for the linear classifiers on frozen embeddings (MCC ${f(A.gap_by_group['Frozen ESM-2, linear'].m425, 3)} on Ind_425 and ${f(A.gap_by_group['Frozen ESM-2, linear'].m1049, 3)} on Ind_1049, mean of the three models) and for one gradient-boosted model on the hand-crafted features (${f(G('AAC_DPC_CTD_LGBM').m425)} and ${f(G('AAC_DPC_CTD_LGBM').m1049)}), and it is larger for the flexible non-linear models: the multilayer perceptron on the 8M embedding (${f(G(M8).m425)} and ${f(G(M8).m1049)}), the random forest and the radial-basis support vector machine on composition (above), the convolutional network (${f(G('B2_cnn_lam0').m425)} and ${f(G('B2_cnn_lam0').m1049)}) and the random forest on the 650M embedding fused with the hand-crafted features (${f(G('esm650_fusion|rf').m425)} and ${f(G('esm650_fusion|rf').m1049)}). In this sense the inflation is largest for flexible non-linear models.`));
add(P(`It is not, however, a monotonic function of capacity, and it should not be described as one. The 650M multilayer perceptron, with far more input dimensions than the 8M model, drops no further than AAC + RF on 21 inputs, and the Transformer (B5) and the fine-tuned 8M model, both of high capacity, sit at the lower end of the non-linear models (Table ${ref('tab:gaps')}). The gap was therefore tested directly (Table ${ref('tab:gapc')}). The test uses the ensemble predictions of each model, 2,000 paired stratified bootstrap resamples of the test peptides, in which the gap of every model is recomputed on the same resample, and Benjamini–Hochberg correction. <b>Flexibility matters:</b> the mean gap of the 32 flexible non-linear models exceeds that of the three linear classifiers by ${sg(gc('Flexible non-linear (all) - Linear', 'both', 'diff'))} MCC (95% interval ${sg(gc('Flexible non-linear (all) - Linear', 'both', 'lo'))} to ${sg(gc('Flexible non-linear (all) - Linear', 'both', 'hi'))}; adjusted p ${f(gc('Flexible non-linear (all) - Linear', 'both', 'p_BH_within_scope'), 4)}; ${sg(gc('Flexible non-linear (all) - Linear', 'ind_425', 'diff'))} on Ind_425 and ${sg(gc('Flexible non-linear (all) - Linear', 'ind_1049', 'diff'))} on Ind_1049), and a model-level Mann–Whitney test, which counts each model once, gives p ${f(gc('Flexible non-linear (all) - Linear', 'both', 'p_mannwhitney_models'), 3)}. <b>Scale does not:</b> across the multilayer perceptrons on the 8M, 35M, 150M and 650M embeddings the gap changes by ${sg(gc('Capacity: slope of gap per decade of parameters (8M, 35M, 150M, 650M MLP)', 'both', 'diff'))} MCC per decade of parameters (95% interval ${sg(gc('Capacity: slope of gap per decade of parameters (8M, 35M, 150M, 650M MLP)', 'both', 'lo'))} to ${sg(gc('Capacity: slope of gap per decade of parameters (8M, 35M, 150M, 650M MLP)', 'both', 'hi'))}; adjusted p ${f(gc('Capacity: slope of gap per decade of parameters (8M, 35M, 150M, 650M MLP)', 'both', 'p_BH_within_scope'), 2)}), a slope that is flat within its interval, and the fine-tuned 8M model has a smaller gap than the multilayer perceptrons on frozen vectors (${sg(gc('Fine-tuned - MLP (frozen vectors)', 'both', 'diff'))}; interval ${sg(gc('Fine-tuned - MLP (frozen vectors)', 'both', 'lo'))} to ${sg(gc('Fine-tuned - MLP (frozen vectors)', 'both', 'hi'))}). What separates the models with a large gap from those with a small one is therefore the flexibility of the classifier placed on the representation and not the size of the language model that produced it. Gradient-boosted trees lie in between: their gap is ${f(gc('LightGBM (6) - Linear', 'both', 'diff'))} MCC above that of the linear classifiers (interval ${sg(gc('LightGBM (6) - Linear', 'both', 'lo'))} to ${sg(gc('LightGBM (6) - Linear', 'both', 'hi'))}) and ${f(-gc('LightGBM (6) - Random forest (6)', 'both', 'diff'))} MCC below that of the random forests (interval ${sg(-gc('LightGBM (6) - Random forest (6)', 'both', 'hi'))} to ${sg(-gc('LightGBM (6) - Random forest (6)', 'both', 'lo'))}). Three limits apply. The test treats the models as fixed and is about these test peptides. Only three linear classifiers were evaluated, all logistic regression on ESM-2 embeddings, and they also score lower in absolute terms, so part of their smaller gap may be that they have less to lose. The gap values of this test come from ensemble predictions, whereas Table ${ref('tab:gaps')} and the numbers above it are means over single models, so the two differ for the neural models.`));
add(caption('tab:gapc', 'Contrasts between the leakage gaps (MCC in Regime A minus MCC in Regime B) of model families. Differences of mean gaps, with the 95% bootstrap interval and the Benjamini–Hochberg adjusted p-value for the average of the two test sets; the model-level Mann–Whitney p-value counts each model once. Source: results/tables/T5.12b_leakage_gap_family_contrasts.csv.'));
{ const names = ['Flexible non-linear (all) - Linear', 'Trees - Linear', 'Kernel SVM - Linear', 'MLP - Linear', 'Residue-level network - Linear', 'Fine-tuned - Linear', 'LightGBM (6) - Linear', 'Random forest (6) - Linear', 'LightGBM (6) - Random forest (6)', 'Trees - MLP', 'Trees - Residue-level network', 'MLP - Residue-level network', 'Fine-tuned - MLP (frozen vectors)', 'Capacity: slope of gap per decade of parameters (8M, 35M, 150M, 650M MLP)'];
  const gt = [['Contrast', 'Ind_425', 'Ind_1049', 'Mean of both [95% interval]', 'BH p', 'MW p (models)']];
  for (const nm of names) { const r = GAPC.find((x) => x.contrast === nm && x.scope === 'both'); gt.push([nm.replace('Capacity: slope of gap per decade of parameters (8M, 35M, 150M, 650M MLP)', 'Capacity: slope per decade of parameters (8M to 650M MLP)').replace(' - ', ' minus '), sg(gc(nm, 'ind_425', 'diff')), sg(gc(nm, 'ind_1049', 'diff')), `${sg(Number(r.diff))} [${sg(Number(r.lo))}, ${sg(Number(r.hi))}]`, f(Number(r.p_BH_within_scope), 4), r.p_mannwhitney_models === '' ? '–' : f(Number(r.p_mannwhitney_models), 3)]); }
  add(table(gt, [3700, 900, 900, 2160, 800, 900], { size: 16 }), afterTable()); }
add(H3('4.4.4 The overlap is a property of the pairing of the files'));
add(P(`If the inflation is caused by the overlap between the two lineages, it should disappear when training and test sets come from the same lineage, because each lineage is internally disjoint, and it should reappear when the lineages are crossed. Figure ${ref('fig:xb')} reports exactly this test, for AAC + RF and the 650M model, across all pairings of three training sets (the AIPpred benchmark, the AntiInflam training set and the combined collection) with the two independent sets. When the training set and the independent set come from the same lineage (the AIPpred benchmark with the AIPpred independent set, the AntiInflam training set with the AntiInflam validation set), the score in Regime A is identical to that in Regime B, because nothing is removed (AAC + RF: ${f(A.xb['AIPpred_benchmark|AIPpred_independent'].rf_A)} and ${f(A.xb['AntiInflam_training|AntiInflam_validation'].rf_A)}). When the lineages are crossed, the score falls once the overlap is removed: AAC + RF from ${f(A.xb['AIPpred_benchmark|AntiInflam_validation'].rf_A)} to ${f(A.xb['AIPpred_benchmark|AntiInflam_validation'].rf_B)} (AIPpred benchmark to the AntiInflam validation set) and from ${f(A.xb['AntiInflam_training|AIPpred_independent'].rf_A)} to ${f(A.xb['AntiInflam_training|AIPpred_independent'].rf_B)} (AntiInflam training set to the AIPpred independent set), and the 650M model from ${f(A.xb['AIPpred_benchmark|AntiInflam_validation'].esm_A)} to ${f(A.xb['AIPpred_benchmark|AntiInflam_validation'].esm_B)} and from ${f(A.xb['AntiInflam_training|AIPpred_independent'].esm_A)} to ${f(A.xb['AntiInflam_training|AIPpred_independent'].esm_B)}. The combined collection used throughout the thesis is, by construction, a crossed pairing for both independent sets.`));
add(figure('fig:xb', 'fig5_10_cross_benchmark_heatmap.png', 'MCC of AAC + RF, the frozen 650M multilayer perceptron and the frozen 8M multilayer perceptron (λ = 0) for each combination of training set (rows) and independent set (columns), in Regimes A, B and C.', 560));
add(P(`Because the training sets differ in size and composition, the values in different cells of Figure ${ref('fig:xb')} are not directly comparable as measures of how good a method is; the comparison that matters is between Regime A and Regime B within one cell. By that comparison, the overlap inflates the score in the two crossed cells and in the combined file, and in no within-lineage cell. This pattern agrees with the explanation given in Chapter 3, and it excludes the alternative that the inflation arises from the removal procedure itself, because the procedure removes nothing in the within-lineage cells.`));
add(H3('4.4.5 What this does and does not show'));
add(P(`The measurements concern the distributed files. They show that a model trained on the combined collection and evaluated on the independent sets as distributed receives a score that is higher than its score on the non-overlapping part of the same sets, by 0.03 to 0.38 MCC depending on the model. They do not show that any published result was affected, because a published model may have been trained and tested on a different pairing of the files, and they do not measure the effect on any model that was not trained here. The result is, moreover, a result about the particular combinations of the two lineages that exist in the files: whether the larger set of AIP resources contains other overlaps was not examined. The practical consequence is nevertheless clear: a user who trains on a combined collection of these resources, and tests on either independent set as distributed, should expect an overestimate of about 0.14 to 0.34 MCC for the flexible non-linear models of Table ${ref('tab:gaps')}, and should report the score on the sequences that do not overlap.`));

// ---------------------------------------------------------------- 5.5
add(H2('4.5 Does the Contrastive Objective Improve Prediction?'));
add(H3('4.5.1 The λ sweep'));
add(P(`Figure ${ref('fig:lambda')} shows the effect of λ for the multilayer perceptron on the 8M embedding at τ = 0.07. The cross-validated MCC rises from ${f(A.lam['0'].cv_mcc, 4)} at λ = 0 to ${f(A.lam['2'].cv_mcc, 4)} at λ = 2, an increase of ${f(A.lam['2'].cv_mcc - A.lam['0'].cv_mcc, 4)}, while the standard deviation over the 25 runs is ${f(A.lam['0'].cv_sd, 3)}; the dependence on λ is not monotonic (the value at λ = 1 is lower than at λ = 0.5), and the AUROC changes by 0.004. On the independent sets in Regime B, the MCC at λ = 2 is ${f(A.lam['2'].b425)} on Ind_425 (λ = 0: ${f(A.lam['0'].b425)}) and ${f(A.lam['2'].b1049)} on Ind_1049 (${f(A.lam['0'].b1049)}), so that the sign of the change differs between the sets. The grid of λ ends at 2, and the best CV value is at the edge of the grid; a larger weight was not examined, so that the sweep does not exclude a benefit at weights above 2.`));
add(figure('fig:lambda', 'fig5_4_lambda_sweep.png', 'Cross-validated MCC as a function of λ for the multilayer perceptron on four ESM-2 checkpoints (mean ± standard deviation over 25 runs). The dotted line marks λ = 0, the model without the contrastive term.', 420));
add(H3('4.5.2 The other checkpoints and the temperature'));
add(P(`For the four checkpoints, the best λ > 0 improves the cross-validated MCC by ${sg(Math.min(...T.checkpoints.slice(1).map((r) => parseFloat(r[4]))), 4)} to ${sg(Math.max(...T.checkpoints.slice(1).map((r) => parseFloat(r[4]))), 4)} (Table ${ref('tab:checkpoints')}), always less than one third of the standard deviation between runs. In Regime B the change is positive for two combinations of checkpoint and set (8M and 35M on Ind_425) and negative for the other six (150M and 650M on both sets, and 8M and 35M on Ind_1049). The temperature (Table ${ref('tab:tau')} of Appendix A) was then chosen at the selected λ; within a checkpoint it changes the cross-validated MCC by at most 0.009, less than the standard deviation between runs, and it is not analysed further.`));
add(caption('tab:checkpoints', 'Effect of the best SupCon weight at the four ESM-2 checkpoints (multilayer perceptron). The Regime B columns give MCC at λ = 0 and at the selected λ, mean over five final models.'));
add(table(T.checkpoints, [1400, 800, 1500, 1500, 1000, 1580, 1580], { size: 17 }), afterTable());
add(H3('4.5.3 The primary hypothesis (H1)'));
add(P(`H1 stated that at the 8M checkpoint the model with λ > 0 has a higher MCC than the model with λ = 0 on both leakage-free independent sets. The outcome of the test had been seen in the first part of the study, and the pre-registration records that (Chapter 3). On Ind_425 (n = ${H.ind_425.n}) the difference in MCC is ${ci(H.ind_425)} and on Ind_1049 (n = ${H.ind_1049.n}) ${ci(H.ind_1049)}; the DeLong p-values for the AUROC difference are ${f(H.ind_425.p, 2)} and ${f(H.ind_1049.p, 2)}. The lower bound of the interval is below zero on both sets, so H1 is not supported. The two intervals also exclude differences of more than about ${f(H.ind_425.hi, 2)} MCC (Ind_425) and ${f(H.ind_1049.hi, 2)} (Ind_1049) in favour of the contrastive term at the 95% level, and the minimum detectable effect of the individual comparisons was ${f(H.ind_425.mde, 2)} and ${f(H.ind_1049.mde, 2)} (Section 4.8).`));
add(H3('4.5.4 Six architectures (H2)'));
add(P(`H2 repeated the contrast in the residue-level architectures B2 to B6 of Chapter 3, on both leakage-free sets (10 comparisons), with the rule that a comparison supports the claim only if the BH-adjusted DeLong p is below 0.05 and the lower bound of the MCC interval is above zero. Table ${ref('tab:arch')} gives the results with the raw and the adjusted p-values side by side. <b>None of the ten comparisons meets the rule</b>; the smallest adjusted p-value is ${f(Math.min(...Object.entries(A.h2).filter(([k]) => !k.startsWith('B1')).map(([, v]) => v.bh)), 3)} (the convolutional network on Ind_1049), and its ΔMCC is negative. Two intervals exclude zero in favour of the contrastive term (the BiLSTM and the CNN-BiLSTM on Ind_425: ${ci(A.h2['B3_bilstm|ind_425'])} and ${ci(A.h2['B4_cnn_bilstm|ind_425'])}), but in both cases the difference in AUROC is small (${sg(A.h2['B3_bilstm|ind_425'].dauroc)} and ${sg(A.h2['B4_cnn_bilstm|ind_425'].dauroc)}) and not significant (DeLong p ${f(A.h2['B3_bilstm|ind_425'].p, 2)} and ${f(A.h2['B4_cnn_bilstm|ind_425'].p, 2)}). A change in MCC without a change in AUROC is a change in the threshold position and not in the ranking of peptides; this is why the rule includes the AUROC test. The row for B1 in the table is the v1 multilayer perceptron at τ = 0.07 and is not part of H2.`));
add(caption('tab:arch', 'The contrast λ* versus λ = 0 in six architectures on the frozen 8M embedding, Regime B. ΔMCC is for the seed-ensemble predictions; the p-values are DeLong p-values for the AUROC difference, raw and Benjamini–Hochberg adjusted. The rows B2 to B6 are the 10 comparisons of H2, adjusted within that family; the row B1 belongs to the family "λ contrasts in Phase B" and is not part of H2.'));
add(table(T.arch, [1500, 420, 700, 700, 1400, 800, 800, 1400, 800, 840], { size: 16 }), afterTable());
add(H3('4.5.5 All comparisons and their correction'));
add(P(`In all, ${A.lamtests.n} comparisons contrasted a model with λ > 0 and its λ = 0 counterpart (H1, H2, the other regimes, the four checkpoints and the cross-benchmark cells). Of these, ${A.lamtests.raw} are significant at the 5% level before correction, ${A.lamtests.fam} after correction within their families and ${A.lamtests.glob} after the global correction. The survivors are listed in Table ${ref('tab:survivors')}. <b>Every survivor in Regime B or C is negative</b>: the contrastive term lowered the AUROC of the 150M and 650M models on Ind_1049 by 0.02. The only positive survivor is in Regime A (the 8M multilayer perceptron on Ind_425, ΔAUROC +0.016, global BH p 0.048), the regime that contains the overlap, and it disappears in Regime B. The negative survivors in Regime A (the CNN-BiLSTM on Ind_1049 and attention pooling on Ind_425) are likewise on sets that contain the overlap. Cross-benchmark, ${A.xb_tests.raw} of the ${A.xb_tests.n} comparisons is significant before correction and none after; ${A.xb_tests.pos} of the ${A.xb_tests.n} differences are positive and ${A.xb_tests.n - A.xb_tests.pos} negative, with ΔMCC from ${sg(A.xb_tests.min)} to ${sg(A.xb_tests.max)}. Table ${ref('tab:families')} gives the counts for every family of tests.`));
const surv = [['Model and contrast', 'Test set', 'Regime', 'ΔAUROC', 'ΔMCC', 'BH p (family)', 'BH p (global)']];
for (const s of A.lam_survivors) surv.push([s.comparison.replace('lambda*=', 'λ* = ').replace('lambda=2 vs 0', 'λ = 2 vs 0').replace('esm2_t30_150M', 'ESM-2 150M').replace('esm2_t33_650M', 'ESM-2 650M').replace('B1_mlp (v1 MLP, tau 0.07)', '8M MLP (B1, τ = 0.07)').replace('B4_cnn_bilstm', 'B4 CNN-BiLSTM').replace('B6_attnpool', 'B6 attention pooling'), s.test_set === 'ind_425' ? 'Ind_425' : 'Ind_1049', s.regime, sg(s.dauroc), sg(s.dmcc), f(s.bh_fam, 4), f(s.bh_glob, 4)]);
add(caption('tab:survivors', 'The λ-contrasts that remain significant after Benjamini–Hochberg correction (within family or globally). A negative ΔAUROC means that the model with the contrastive term ranks peptides worse.'));
add(table(surv, [2800, 900, 800, 1000, 1000, 1400, 1460], { size: 17 }), afterTable());
add(caption('tab:families', 'Number of comparisons in each family of tests, with the number significant at 5% before correction, after correction within the family, and after the global correction over all comparisons. Source: results/tables/T5.11_corrected_significance.csv.'));
add(table(T.families.map((r) => [r[0].replace('lambda contrast', 'λ contrast'), ...r.slice(1)]), [3600, 900, 1500, 1800, 1560], { size: 17 }), afterTable());
add(H3('4.5.6 Nested cross-validation and in-distribution effects'));
add(P(`The λ selected by cross-validation is itself a choice, so that its benefit has to be measured on data not used for the choice. In the nested cross-validation (outer 5 × 5 folds, inner three-fold selection of λ on the training part), the outer MCC was ${f(ND.lam0, 4)} with λ = 0 and ${f(ND.sel, 4)} with the selected λ, a difference of ${sg(ND.diff, 4)} (95% interval ${sg(ND.lo, 4)} to ${sg(ND.hi, 4)}, n = ${ND.n}; standardised effect ${f(ND.dz, 2)}). The selected λ varied between folds (0.5 in ${ND.sel_counts['0.5']} of the 25 outer folds, 2 in ${ND.sel_counts['2']}, 0.25 in ${ND.sel_counts['0.25']}, 1 in ${ND.sel_counts['1']} and 0.1 in ${ND.sel_counts['0.1']}), which is what a quantity without a stable optimum looks like. The nested scores are lower than those in Table ${ref('tab:cv')}; in the nested runs the early stopping used a 10% hold-out of the outer-training part and not the validation fold, which may account for it, and only the difference between the two arms is interpreted.`));
add(P(`In the in-distribution cross-validation, ${A.cv_lam2_positive} of the ${A.cv_lam2_total} architectures show a small gain at λ = 2 (from +0.003 to +0.014 MCC, largest for the Transformer, +${f(A.cv_effect['B5_transformer lambda=2 vs 0 (CV)'].diff, 4)}, standardised effect ${f(A.cv_effect['B5_transformer lambda=2 vs 0 (CV)'].dz, 2)}). These gains are of a size that the independent sets could not have detected (Section 4.8), they treat the 25 overlapping runs as independent and are therefore optimistic, and they do not carry over to Regime B. The honest summary is that a small benefit in the order of 0.01 MCC in the training distribution can be neither confirmed nor excluded, and that no benefit of a size that would matter in practice, more than about 0.08 to 0.14 MCC on the leakage-free sets, was found. Cross-validation scores varied between seeds as much as, or more than, any of these effects: the standard deviation of the per-seed MCC differences between λ > 0 and λ = 0 ranges from ${f(A.seed_sd_range[0], 3)} to ${f(A.seed_sd_range[1], 3)} over the comparisons.`));

add(H3('4.5.7 The latent space'));
const cm = (set) => fs.readFileSync(`${ROOT}/results/tables/cluster_metrics_${set}.csv`, 'utf8').trim().split('\n').slice(1).map((l) => { const m = l.match(/^(".*?"|[^,]*),([^,]*),([^,]*),([^,]*)$/); return [m[1].replace(/"/g, ''), parseFloat(m[3]), parseFloat(m[4])]; });
const c425 = cm('ind_425'), c1049 = cm('ind_1049');
add(P(`Objective 3 also asked how the contrastive term changes the geometry of the latent space. For one model of the 8M multilayer perceptron (seed 0) the raw embedding, the 256-dimensional encoder output at λ = 0 and the encoder output at λ = 2 were computed for the Regime B sequences of each set, and the separation of the two classes was summarised by the silhouette coefficient (higher is better separated) and the Davies–Bouldin index (lower is better) with the class labels as the clusters (Figure ${ref('fig:tsne')}). The silhouette coefficients are close to zero in all three spaces: on Ind_425 ${f(c425[0][1], 3)} (raw), ${f(c425[1][1], 3)} (λ = 0) and ${f(c425[2][1], 3)} (λ = 2), and on Ind_1049 ${f(c1049[0][1], 3)}, ${f(c1049[1][1], 3)} and ${f(c1049[2][1], 3)}. The Davies–Bouldin index falls from ${f(c425[0][2], 1)} (raw) to ${f(c425[1][2], 1)} at λ = 0 and ${f(c425[2][2], 1)} at λ = 2 on Ind_425, and from ${f(c1049[0][2], 1)} to ${f(c1049[1][2], 1)} and ${f(c1049[2][2], 1)} on Ind_1049, so that the encoder trained with the classification loss alone already improves the separation relative to the raw embedding, and the contrastive term adds a further small change in the Davies–Bouldin index and a change in the silhouette whose sign differs between the sets. These are descriptive values of a single model on each set, without uncertainty, and the classes are not visibly separated in any of the panels. The geometry therefore does not provide an additional signal in favour of the contrastive term, in agreement with the classification results.`));
add(figure('fig:tsne', 'fig5_3_tsne_ind_1049.png', `t-SNE ${cit('vandermaaten2008')} projections of the Regime B sequences of Ind_1049 for one 8M model (seed 0): raw frozen embedding, encoder output at λ = 0 and encoder output at λ = 2, with the two classes distinguished by marker shape (open circles non-AIP, filled triangles AIP) so that the panels read in black and white, and silhouette and Davies-Bouldin values in the panel titles.`, 620));

// ---------------------------------------------------------------- 5.6
add(H2('4.6 The Representation: Pooling, Fusion and Fine-Tuning'));
add(P(`The comparison of Section 4.1 shows that frozen ESM-2 embeddings under a small classifier are worse than amino acid composition. Three explanations were examined: that mean pooling discards signal (pooling, C1), that the embedding lacks information that composition provides (fusion, C2), and that the frozen representation is not adapted to the task (fine-tuning, C3). All analyses of this section are exploratory.`));
add(P(`<b>Principal result.</b> Fine-tuning the 8M model brings it above the frozen 650M model, which has 80 times more parameters, in cross-validation (MCC ${f(A.ft_cv.esm2_t6_8M_finetune.mcc)} against ${f(A.ft_cv['esm2_t33_650M_lam0_tau0.07'].mcc)}) and on Ind_1049 in Regime B (ΔMCC ${RT('ESM-2 8M fine-tuned vs frozen 650M MLP (lambda=0)', 'Ind_1049')[2]}, see Section 4.6.3), and it does not distinguish itself from the frozen 650M model on Ind_425. It remains below AAC + RF in cross-validation (${f(A.ft_cv.AAC_RF.mcc)}) and on Ind_425.`));
add(H3('4.6.1 Pooling'));
add(P(`On the frozen 650M embeddings, six ways of summarising the residue vectors were compared with the multilayer perceptron (Table ${ref('tab:pool5')}). The highest cross-validated MCC is obtained with the classification token (CLS, ${f(A.pool_cv['esm650_cls|mlp'])}), against ${f(A.pool_cv['esm650_mean|mlp'])} for mean pooling, ${f(A.pool_cv['esm650_attention|attn_mlp'])} for attention pooling, ${f(A.pool_cv['esm650_meanmax|mlp'])} for the concatenation of mean and maximum, ${f(A.pool_cv['esm650_max|mlp'])} for maximum pooling and ${f(A.pool_cv['esm650_firstlast|mlp'])} for the first and last residues. None of them approaches AAC + RF (${f(A.pool_cv.AAC_RF)}). On the independent sets in Regime B no variant is significantly better than mean pooling after correction, and two (the concatenation of mean and maximum on Ind_1049 and the first and last residues on Ind_1049) are significantly worse (BH p ${f(rp('650M meanmax vs mean pooling (MLP)', 'ind_1049').bh, 3)} and ${f(rp('650M firstlast vs mean pooling (MLP)', 'ind_1049').bh, 4)}). The choice of pooling therefore does not explain the gap.`));
add(caption('tab:pool5', 'Pooling variants on the frozen 650M embedding (multilayer perceptron, λ = 0), with AAC + RF for reference. Cross-validated scores are means over 25 runs; the Regime B columns are means over five final models.'));
add(table(T.pooling, [2900, 900, 900, 1200, 1200, 1130, 1130], { size: 17 }), afterTable());
add(H3('4.6.2 Fusion'));
add(P(`Concatenating the ESM-2 embedding with the hand-crafted features (Table ${ref('tab:fusion')}) gives cross-validated MCC ${f(A.fus_cv['esm8_fusion|rf'].mcc)} (8M) and ${f(A.fus_cv['esm650_fusion|rf'].mcc)} (650M) with the random forest, and ${f(A.fus_cv['esm8_fusion|lgbm'].mcc)} and ${f(A.fus_cv['esm650_fusion|lgbm'].mcc)} with LightGBM, against ${f(A.fus_cv['hand|rf'].mcc)} and ${f(A.fus_cv['hand|lgbm'].mcc)} for the hand-crafted features alone. Fusion is far better than the embedding alone (for LightGBM by 0.2 to 0.26 MCC), and no better than the composition features alone: in Regime B, the fusion of the 650M embedding with the random forest differs from the hand-crafted features alone by ${ci(rp('esm650 fusion vs hand-crafted only (rf)', 'ind_425'))} (BH p ${f(rp('esm650 fusion vs hand-crafted only (rf)', 'ind_425').bh, 2)}) and ${ci(rp('esm650 fusion vs hand-crafted only (rf)', 'ind_1049'))} (BH p ${f(rp('esm650 fusion vs hand-crafted only (rf)', 'ind_1049').bh, 2)}). The signal that the classifiers use comes from the composition features, and the embedding adds nothing that these classifiers can exploit.`));
add(caption('tab:fusion', 'Hand-crafted features, ESM-2 embeddings and their concatenation with three classifiers. Cross-validated scores are means over 25 runs; the Regime B columns are means over five final models.'));
add(table(T.fusion, [3000, 800, 800, 1200, 1200, 1180, 1180], { size: 17 }), afterTable());
add(H3('4.6.3 Fine-tuning'));
add(P(`Table ${ref('tab:ft5')} compares the fine-tuned 8M model with its frozen control (same head, loop and folds) and with the references. Fine-tuning raises the cross-validated MCC from ${f(A.ft_cv.esm2_t6_8M_frozen.mcc)} to ${f(A.ft_cv.esm2_t6_8M_finetune.mcc)} and the AUROC from ${f(A.ft_cv.esm2_t6_8M_frozen.auroc)} to ${f(A.ft_cv.esm2_t6_8M_finetune.auroc)}. In Regime B the gain is ${RT('ESM-2 8M fine-tuned vs frozen (same head)', 'Ind_425')[2]} on Ind_425 (BH p ${RT('ESM-2 8M fine-tuned vs frozen (same head)', 'Ind_425')[5]}) and ${RT('ESM-2 8M fine-tuned vs frozen (same head)', 'Ind_1049')[2]} on Ind_1049 (BH p below 0.0001). <b>The fine-tuned 8M model also exceeds the frozen 650M model</b> in cross-validation (${f(A.ft_cv.esm2_t6_8M_finetune.mcc)} against ${f(A.ft_cv['esm2_t33_650M_lam0_tau0.07'].mcc)}) and on Ind_1049 in Regime B, where the difference in MCC is ${RT('ESM-2 8M fine-tuned vs frozen 650M MLP (lambda=0)', 'Ind_1049')[2]} and the AUROC difference ${RT('ESM-2 8M fine-tuned vs frozen 650M MLP (lambda=0)', 'Ind_1049')[3]} (BH p ${RT('ESM-2 8M fine-tuned vs frozen 650M MLP (lambda=0)', 'Ind_1049')[5]}); on Ind_425 the difference is ${RT('ESM-2 8M fine-tuned vs frozen 650M MLP (lambda=0)', 'Ind_425')[2]} (BH p ${RT('ESM-2 8M fine-tuned vs frozen 650M MLP (lambda=0)', 'Ind_425')[5]}), which is not distinguishable from zero with n = 214. The comparison with the frozen 650M model was added after the results were seen and is exploratory (Section 3.14). The paired comparisons of the whole representation study are listed in Table ${ref('tab:reptests')} of Appendix A.`));
add(P(`Against AAC + RF, the fine-tuned model is lower in cross-validation (${f(A.ft_cv.esm2_t6_8M_finetune.mcc)} against ${f(A.ft_cv.AAC_RF.mcc)}), significantly lower on Ind_425 (${RT('8M fine-tuned vs AAC+RF', 'Ind_425')[2]}; BH p ${RT('8M fine-tuned vs AAC+RF', 'Ind_425')[5]}) and not distinguishable on Ind_1049 (${RT('8M fine-tuned vs AAC+RF', 'Ind_1049')[2]}; BH p ${RT('8M fine-tuned vs AAC+RF', 'Ind_1049')[5]}). Adapting the representation therefore closes the gap on Ind_1049, where the difference from AAC + RF is not distinguishable from zero, and only part of it on Ind_425, where the fine-tuned model remains 0.109 MCC lower; it does not reverse the ordering in either. Two qualifications limit this result: fine-tuning was done for the 8M model only, with one hyperparameter setting and three repetition seeds, and the frozen and fine-tuned runs both stopped on the validation fold (Section 3.13). The result supports the statement that adaptation matters, and does not support the statement that ESM-2 outperforms composition.`));
add(caption('tab:ft5', 'The fine-tuned 8M model and its comparators. Cross-validated scores: 15 runs for the fine-tuned and frozen-control rows, 25 runs for the others; Regime B columns are means over the final models.'));
add(table(T.finetune, [2900, 800, 900, 1200, 1200, 1130, 1130], { size: 17 }), afterTable());

